{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-7",
      "explanation": "The method concatenates the caller-provided searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially read or modify data beyond their permissions.",
      "remediation": "Replace the dynamic query with a static SOQL statement that uses a bind variable, e.g. `SELECT Id, Name, Industry FROM Account WHERE Name LIKE :('%' + searchKey + '%') LIMIT 50`, or escape the input with `String.escapeSingleQuotes(searchKey)` before concatenation."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Missing FLS enforcement on SOSL query",
      "severity": "Medium",
      "file": "InvoiceSearchController.cls",
      "lines": "4-10",
      "explanation": "The SOSL query returns Invoice__c fields without enforcing field‑level security. Users who have read access to the object can see all returned fields, potentially exposing data they should not view.",
      "remediation": "Add WITH SECURITY_ENFORCED to the SOSL query or use Security.stripInaccessible to filter out inaccessible fields before returning the results."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via dynamic query",
      "severity": "High",
      "file": "ReportFilterController.cls",
      "lines": "6-13",
      "explanation": "The method concatenates raw client‑supplied filter strings into a SOQL WHERE clause without any escaping or allow‑listing, allowing an attacker to inject arbitrary SOQL clauses and potentially access or modify data beyond their permissions.",
      "remediation": "Replace the dynamic string construction with bind variables or Database.queryWithBinds, and enforce an allow‑list of permitted field names. Escape any literal values with String.escapeSingleQuotes or use a static SOQL query with bind variables for each filter."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security bypass",
      "severity": "Medium",
      "file": "AccountRatingService.cls",
      "lines": "4-10",
      "explanation": "The SOQL query and DML operation run in system mode, ignoring field‑level security. This allows users without read access to AnnualRevenue to view it and users without edit access to Rating to modify it.",
      "remediation": "Add WITH USER_MODE to the SOQL query or use Security.stripInaccessible to enforce FLS, and perform explicit FLS checks before updating fields."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Unenforced Task Creation FLS Violation",
      "severity": "Medium",
      "file": "CaseEscalationService.cls",
      "lines": "15-23",
      "explanation": "The method creates a Task record without checking field-level security or object permissions. The permission set explicitly denies Task creation, yet the code inserts a Task, allowing users to create records they should not be able to. The exception is swallowed, hiding the violation from callers.",
      "remediation": "Validate FLS before DML: use Security.stripInaccessible or check Task.isCreateable() and Task.isFieldAccessible() for each field. Perform the insert with \"insert as user\" and \"with security enforced\" or remove the Task creation logic if the permission set should not allow it. Also avoid swallowing DmlException; surface the error to the caller."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in Aura-enabled class",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-10",
      "explanation": "The class is declared \"without sharing\" and exposes an @AuraEnabled method that returns Case records. Because sharing rules are ignored, users who have object read access can see any Case record, regardless of record‑level sharing restrictions.",
      "remediation": "Declare the class with \"with sharing\" or use a SOQL clause with WITH USER_MODE to enforce sharing. Alternatively, manually filter the query results to only include records the current user is allowed to see."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass",
      "severity": "High",
      "file": "FinancialDashboardController.cls",
      "lines": "1-8",
      "explanation": "The class is declared without sharing and exposes an @AuraEnabled method that queries all Opportunity records with WITH USER_MODE. Because the class ignores sharing rules, partner community users can retrieve every Opportunity they have object‑level read access to, bypassing record‑level sharing restrictions.",
      "remediation": "Declare the class or method with \"with sharing\" (or \"inherited sharing\") and remove the WITH USER_MODE clause if not needed, or explicitly filter the query to only return records the user should see. This ensures record‑level sharing is respected for external callers."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in DataAggregator",
      "severity": "High",
      "file": "DataAggregator.cls",
      "lines": "1-20",
      "explanation": "The class is declared 'without sharing', so all SOQL queries run in system mode and ignore record‑level sharing. The @AuraEnabled method getLeadSummary can be invoked by any user granted the class via the permission set, allowing them to read all Lead records, including those they should not see.",
      "remediation": "Declare the class with 'with sharing' (or 'inherited sharing') or add a 'with sharing' keyword to the method. Alternatively, enforce sharing programmatically using Security.stripInaccessible or by querying with a sharing context. This ensures that users can only access records they are permitted to see."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions in Support Agent Tools Permission Set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled, which far exceed the described purpose of allowing tier‑1 support agents to view and close cases. These system permissions enable the user to read, modify, and delete any record in the org, creating a privilege escalation risk.",
      "remediation": "Remove the unnecessary system permissions from the permission set. Grant only the Case object CRUD permissions (allowRead, allowEdit) and the ApiEnabled permission if the class is called via REST or Aura. If Apex execution is required, grant only AuthorApex to the specific class or use a dedicated Apex class permission instead of the global permission."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permission Set Privileges",
      "severity": "Medium",
      "file": "Accounts_Payable_Clerk.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ManageInternalUsers system permission, which allows users to manage internal users. This privilege is not required for reviewing or approving invoices and violates the principle of least privilege.",
      "remediation": "Remove the ManageInternalUsers permission from the Accounts Payable Clerk permission set or create a separate permission set for user management tasks. Ensure the permission set only contains permissions necessary for invoice approval."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive ViewAllData permission",
      "severity": "High",
      "file": "Report_Viewer_Plus.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ViewAllData permission, which allows users to read all data in the org. This far exceeds the described purpose of regional managers only viewing and exporting reports, exposing sensitive data beyond what is necessary.",
      "remediation": "Remove the ViewAllData permission from the permission set. Grant only the RunReports and ExportReport user permissions and the required object read permissions for the reports and related objects."
    }
  ]
}
